        );

        require(
            address(aToken) != address(0),
            "AaveLendingBridge: NO_LENDING_POOL"
        );
        require(
            underlyingToZkAToken[underlyingAsset] == address(0),
            "AaveLendingBridge: ZK_TOKEN_SET"
        );

        // TODO add AztecAAVEBridge token to name / symbol
        underlyingToZkAToken[underlyingAsset] = address(
            new ZkAToken(aToken.name(), aToken.symbol(), aToken.decimals())
        );
    }

function _enter(address inputAsset, uint256 amount)
        internal
        returns (uint256)
    {
        IPool pool = IPool(addressesProvider.getLendingPool());
        IScaledBalanceToken aToken = IScaledBalanceToken(
            pool.getReserveData(inputAsset).aTokenAddress
        );
        require(
            address(aToken) != address(0),
            "AaveLendingBridge: NO_LENDING_POOL"
        );
        require(
            underlyingToZkAToken[inputAsset] != address(0),
            "AaveLendingBridge: NO_ZK_TOKEN_POOL"
        );

        // 1. Read the scaled balance from the lending pool
        uint256 scaledBalance = aToken.scaledBalanceOf(address(this));

        // 2. Approve totalInputValue to be lent on AAVE
        IERC20Detailed(inputAsset).approve(address(pool), amount);

        // 3. Lend totalInputValue of inputAssetA on AAVE lending pool
        pool.deposit(inputAsset, amount, address(this), 0);

        // 4. Mint the difference between the scaled balance at the start of the interaction and after the deposit as our zkAToken
        uint256 diff = aToken.scaledBalanceOf(address(this)).sub(scaledBalance);
        IERC20Detailed(underlyingToZkAToken[inputAsset]).mint(
            address(this),
            diff
        );

        IERC20Detailed(underlyingToZkAToken[inputAsset]).approve(
            rollupProcessor,
            diff
        );
        return diff;
    }

function _exit(address outputAsset, uint256 scaledAmount)
        internal
        returns (uint256)
    {
        IPool pool = IPool(addressesProvider.getLendingPool());
        IERC20 aToken = IERC20(pool.getReserveData(outputAsset).aTokenAddress);

        // 1. Compute the amount from the scaledAmount supplied
        uint256 underlyingAmount = scaledAmount.rayMul(
            pool.getReserveNormalizedIncome(outputAsset)
        );

        // 2. Lend totalInputValue of inputAssetA on AAVE lending pool and return the amount of tokens
        uint256 outputValue = pool.withdraw(
            outputAsset,
            underlyingAmount,
            address(this)
        );

        IERC20Detailed(outputAsset).approve(rollupProcessor, outputValue);

        // 3. Burn the supplied amount of zkAToken as this has now been withdrawn
        IZkAToken(underlyingToZkAToken[outputAsset]).burn(scaledAmount);

        return outputValue;
    }

function convert(
    AztecTypes.AztecAsset calldata inputAssetA,
    AztecTypes.AztecAsset calldata,
    AztecTypes.AztecAsset calldata outputAssetA,
    AztecTypes.AztecAsset calldata,
    uint256 totalInputValue,
    uint256 interactionNonce,
    uint64 auxData,
    address rollupBeneficiary
  )
    external
    payable
    returns (
      uint256 outputValueA,
      uint256 outputValueB,
      bool isAsync
    )
  {
    // ### INITIALIZATION AND SANITY CHECKS
    require(msg.sender == rollupProcessor, "MStableBridge: INVALID_CALLER");

    require(
      inputAssetA.id != outputAssetA.id,
      "MStableBridge: ASSET_IDS_EQUAL"
    );

    require(
      inputAssetA.assetType == AztecTypes.AztecAssetType.ERC20,
      "MStableBridge: NOT_ERC20"
    );
    // operation is asynchronous
    isAsync = false;

    address mUSD = address(0xe2f2a5C287993345a840Db3B0845fbC70f5935a5);
    address imUSD = address(0x30647a72Dc82d7Fbb1123EA74716aB8A317Eac19);
    address dai = address(0x6B175474E89094C44Da98b954EedeAC495271d0F);

    if (outputAssetA.erc20Address == imUSD) {
      ERC20(inputAssetA.erc20Address).approve(
        address(mUSD),
        totalInputValue
      );

      uint256 minimumMUSDToMint = totalInputValue * ((uint256(10000) - uint256(auxData)))/10000;
      uint256 massetsMinted = IMStableAsset(mUSD).mint(dai, totalInputValue, minimumMUSDToMint, address(this)); // Minting

      ERC20(mUSD).approve(
        imUSD,
        massetsMinted
      );

      outputValueA = IMStableSavingsContract(imUSD).depositSavings(massetsMinted); // Deposit into save

      ERC20(imUSD).approve(
        rollupProcessor,
        outputValueA
      );
    } else {
        uint256 redeemedMUSD = IMStableSavingsContract(imUSD).redeemCredits(totalInputValue);
        uint256 minimumBAssetToRedeem = redeemedMUSD * ((uint256(10000) - uint256(auxData)))/10000;
        uint256 redeemedValue = IMStableAsset(mUSD).redeem(dai, redeemedMUSD, minimumBAssetToRedeem, address(this));
        outputValueA = redeemedValue;
        ERC20(dai).approve(
          rollupProcessor,
          outputValueA
        );
    }
  }

function convert(
    AztecTypes.AztecAsset memory inputAssetA,
    AztecTypes.AztecAsset memory inputAssetB,
    AztecTypes.AztecAsset memory outputAssetA,
    AztecTypes.AztecAsset memory outputAssetB,
    uint256 totalInputValue,
    uint256 interactionNonce,
    uint64 auxData,
    address
  )
    external
    payable
    returns (
      uint256 outputValueA,
      uint256 outputValueB,
      bool isAsync
    )
  {
    // ### INITIALIZATION AND SANITY CHECKS
    require(msg.sender == rollupProcessor, "RaiBridge: INVALID_CALLER");

    if (inputAssetA.assetType == AztecTypes.AztecAssetType.ETH) {
        // transfer to weth
        IWETH(WETH).deposit{value: msg.value}();
    }


    if (isInitialized) {
      (uint collateralRatio, uint raiToEth, ISafeEngine.SAFE memory safe) = getSafeData();
      if (outputAssetA.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetA.erc20Address == RAI) {
        require(outputAssetB.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetB.erc20Address == address(this));
            // deposit weth output RAI
            outputValueA = _addCollateral(totalInputValue, collateralRatio, raiToEth);
            outputValueB = outputValueA;
            _mint(address(this), outputValueB);
        } else if (inputAssetA.assetType == AztecTypes.AztecAssetType.ERC20 && inputAssetA.erc20Address == RAI) {
          _burn(address(this), totalInputValue);
            // deposit RAI output weth
            outputValueA = _removeCollateral(totalInputValue, safe);
            if (outputAssetA.assetType == AztecTypes.AztecAssetType.ETH) {
              // change weth to eth
              IWETH(WETH).withdraw(outputValueA);
              IRollupProcessor(rollupProcessor).receiveEthFromBridge{value: outputValueA}(interactionNonce);
          }
        }
    } else {
        // CONTRACT INITIALIZATION
        require(auxData > 0, "no collateral ratio provided");
        require(outputAssetB.assetType == AztecTypes.AztecAssetType.ERC20 && outputAssetB.erc20Address == address(this));
        isInitialized = true;

        require(IERC20(address(this)).approve(rollupProcessor, type(uint).max), "BridgeTokens approve failed");

        (, int raiToEth, , ,) = priceFeed.latestRoundData();

        // minimum amount of RAI to be borrowed at initialization is 1469 RAI
        // please provide enough ETH/WETH for that or this method will revert
        outputValueA = _addCollateral(totalInputValue, auxData, uint(raiToEth));
        outputValueB = outputValueA;
        _mint(address(this), outputValueB);
    }
  }

function getSafeData() public view returns (uint256 collateralRatio, uint raiToEth, ISafeEngine.SAFE memory safe) {
    safe = ISafeEngine(SAFE_ENGINE).safes(0x4554482d41000000000000000000000000000000000000000000000000000000, SAFE_HANDLER);
     // rai to Eth Ratio
    (, int x, , ,) = priceFeed.latestRoundData();
    raiToEth = uint(x);
    if (safe.lockedCollateral != 0 || safe.generatedDebt != 0) {
      collateralRatio =  safe.lockedCollateral.mul(1e22).div(raiToEth).div(safe.generatedDebt);
    } else {
      collateralRatio = 0;
    }
  }

function _addCollateral(uint _wethAmount, uint _collateralRatio, uint _raiToEth) internal returns (uint outputRai) {
      IEthJoin(ETH_JOIN).join(SAFE_HANDLER, _wethAmount);

      // expected RAI amount = eth_amount * (1e18/raiToEthPrice) * (1/collateralRatio)
      outputRai = _wethAmount.mul(1e22).div(_raiToEth).div(_collateralRatio);

      ISafeManager(SAFE_MANAGER).modifySAFECollateralization(safeId, int(_wethAmount), int(outputRai));

      ISafeManager(SAFE_MANAGER).transferInternalCoins(safeId, address(this), outputRai * 10**27);

      ICoinJoin(COIN_JOIN).exit(address(this), outputRai);
  }

function _removeCollateral(uint _raiAmount, ISafeEngine.SAFE memory safe) internal returns (uint outputWeth) {
        ICoinJoin(COIN_JOIN).join(SAFE_HANDLER, _raiAmount);

        outputWeth = safe.lockedCollateral.mul(_raiAmount).div(safe.generatedDebt);

        ISafeManager(SAFE_MANAGER).modifySAFECollateralization(safeId, -int(outputWeth), -int(_raiAmount));
        ISafeManager(SAFE_MANAGER).transferCollateral(safeId, address(this), outputWeth);
        IEthJoin(ETH_JOIN).exit(address(this), outputWeth);
  }

